typedef struct {
    const char *name;
    const char *source;
    /* The file it was embedded from, emitted beside the source by the Makefile's `embed_zm` so it
     * cannot drift. Carried so that a bundled declaration can name its own file in a diagnostic
     * (`FunctionDecl.origin_file`) -- without it, `--lint-bundled` could see nothing but the
     * prelude, which is why tools/lint_lib.py needed a second route for the rest of lib/. */
    const char *path;
} CoreModule;

/* COLLECTIONS_SOURCE is one long string literal, expected to exceed the
 * C99-mandated minimum translation limit of 4095 characters -- harmless
 * on every compiler this project targets. Silenced narrowly here (right
 * where the macro is actually expanded) rather than loosening
 * -Wpedantic project-wide. */
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Woverlength-strings"
