int corelib_module_count(void) {
    return (int)(sizeof(CORE_MODULES) / sizeof(CORE_MODULES[0]));
}

const char *corelib_module_name(int i) {
    if (i < 0 || i >= corelib_module_count()) return NULL;
    return CORE_MODULES[i].name;
}


/* The multi-file bundled modules. A part's name is its real path, so a diagnostic inside one prints
 * that file and the excerpt comes back with it -- `ziman_register_source` is called with exactly
 * this string. The first part of each is the one carrying the module comment, the imports and the
 * types; the rest are grouped by what they are about, which is how the sections of the single file
 * they came from were already divided.
 *
 * `server` was 2,878 lines and `client` 1,445 before 2026-10-31. Splitting them needed the loader
 * to merge parts for any bundled module rather than for the prelude alone (prelude.c had the only
 * such mechanism, special-cased), which is the change this table is the data for. */
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Woverlength-strings"
static const struct {
    const char *module;
    const char *name;
    const char *source;
} MODULE_PARTS[] = {
    {"server", "lib/http/server/server.zm", SERVER_SERVER_SOURCE},
    {"server", "lib/http/server/read.zm", SERVER_READ_SOURCE},
    {"server", "lib/http/server/respond.zm", SERVER_RESPOND_SOURCE},
    {"server", "lib/http/server/route.zm", SERVER_ROUTE_SOURCE},
    {"server", "lib/http/server/multipart.zm", SERVER_MULTIPART_SOURCE},
    {"server", "lib/http/server/handler.zm", SERVER_HANDLER_SOURCE},
    {"server", "lib/http/server/ratelimit.zm", SERVER_RATELIMIT_SOURCE},
    {"server", "lib/http/server/metrics.zm", SERVER_METRICS_SOURCE},
    {"server", "lib/http/server/cors.zm", SERVER_CORS_SOURCE},
    {"server", "lib/http/server/serve.zm", SERVER_SERVE_SOURCE},
    {"client", "lib/http/client/client.zm", CLIENT_CLIENT_SOURCE},
    {"client", "lib/http/client/read.zm", CLIENT_READ_SOURCE},
    {"client", "lib/http/client/proxy.zm", CLIENT_PROXY_SOURCE},
    {"client", "lib/http/client/send.zm", CLIENT_SEND_SOURCE},
    {"client", "lib/http/client/cookie.zm", CLIENT_COOKIE_SOURCE},
    {"client", "lib/http/client/request.zm", CLIENT_REQUEST_SOURCE},
    {"client", "lib/http/client/stream.zm", CLIENT_STREAM_SOURCE},
};
#pragma GCC diagnostic pop

int corelib_part_count(const char *use_path) {
    int n = 0;
    for (size_t i = 0; i < sizeof MODULE_PARTS / sizeof MODULE_PARTS[0]; i++) {
        if (strcmp(MODULE_PARTS[i].module, use_path) == 0) n++;
    }
    return n;
}

/* The i'th part of `use_path`, in table order. Linear because the table is short and this runs
 * once per `use` of a multi-file module. */
static int part_index(const char *use_path, int i) {
    int seen = 0;
    for (size_t k = 0; k < sizeof MODULE_PARTS / sizeof MODULE_PARTS[0]; k++) {
        if (strcmp(MODULE_PARTS[k].module, use_path) != 0) continue;
        if (seen++ == i) return (int)k;
    }
    return -1;
}

const char *corelib_part_name(const char *use_path, int i) {
    int k = part_index(use_path, i);
    return k < 0 ? NULL : MODULE_PARTS[k].name;
}

const char *corelib_path_for(const char *use_path) {
    size_t n = sizeof(CORE_MODULES) / sizeof(CORE_MODULES[0]);
    for (size_t i = 0; i < n; i++) {
        if (strcmp(use_path, CORE_MODULES[i].name) == 0) return CORE_MODULES[i].path;
    }
    return NULL;
}

char *corelib_whole_source_for(const char *use_path) {
    int parts = corelib_part_count(use_path);
    if (parts == 0) {
        const char *one = corelib_source_for(use_path);
        return one == NULL ? NULL : ziman_xstrdup(one);
    }
    size_t total = 1;
    for (int i = 0; i < parts; i++) total += strlen(corelib_part_source(use_path, i)) + 1;
    char *out = ziman_xmalloc(total);
    out[0] = '\0';
    for (int i = 0; i < parts; i++) {
        strcat(out, corelib_part_source(use_path, i));
        strcat(out, "\n");
    }
    return out;
}

const char *corelib_part_source(const char *use_path, int i) {
    int k = part_index(use_path, i);
    return k < 0 ? NULL : MODULE_PARTS[k].source;
}

const char *corelib_source_for(const char *use_path) {
    /* A multi-file module has no single source, and saying so is what makes a caller that wants
     * one notice (corelib.h). */
    if (corelib_part_count(use_path) > 0) return NULL;
    size_t n = sizeof(CORE_MODULES) / sizeof(CORE_MODULES[0]);
    for (size_t i = 0; i < n; i++) {
        if (strcmp(use_path, CORE_MODULES[i].name) == 0) return CORE_MODULES[i].source;
    }
    return NULL;
}
